package co.serviasigna.domain;

import jakarta.persistence.*;

/**
 * Evento que la app mandó sin conexión y ya se procesó (tabla EVENTO_PROCESADO). Evita duplicados cuando el celular
 * reenvía lo pendiente (RF-M6-11).
 * <p>
 * EN: Event the app sent while offline that was already processed (EVENTO_PROCESADO table). It avoids duplicates when
 * the phone resends what was pending (RF-M6-11).
 */
@Entity
@Table(name = "EVENTO_PROCESADO")
public class ProcessedEvent {
    /** El id único que generó el celular. EN: The unique id generated by the phone. */
    @Id @Column(name = "ID_EVENTO", length = 40) private String eventId;
    /** La fecha en minutos de reloj. EN: The date in clock minutes. */
    @Convert(converter = MinutesConverter.class) @Column(name = "FECHA", nullable = false) private Double date;

    /**
     * Constructor vacío que exige JPA para leer la fila de la base de datos.
     * <p>
     * EN: Empty constructor required by JPA to read the row from the database.
     */
    protected ProcessedEvent() {}

    /**
     * Registra un evento como procesado.
     * <p>
     * EN: Records an event as processed.
     *
     * @param eventId id único que generó el celular / unique id generated by the phone
     * @param date fecha en minutos de reloj / date in clock minutes
     */
    public ProcessedEvent(String eventId, double date) { this.eventId = eventId; this.date = date; }

    /**
     * Devuelve el id único que generó el celular.
     * <p>
     * EN: Returns the unique id generated by the phone.
     *
     * @return el id único que generó el celular / the unique id generated by the phone
     */
    public String getEventId() { return eventId; }

    /**
     * Devuelve la fecha en minutos de reloj.
     * <p>
     * EN: Returns the date in clock minutes.
     *
     * @return la fecha en minutos de reloj / the date in clock minutes
     */
    public Double getDate() { return date; }
}
